"use client";
import { useEffect, useMemo, useState } from "react";
import { AppShell } from "../../ui/app-shell";
import { queueRound, syncQueuedRounds, type DetailedShot } from "../../../lib/offline-sync";
const bands=["Tee shot","Over 200 yd","150–200 yd","125–150 yd","100–125 yd","50–100 yd","Under 50 yd","Bunker","Putting 0–6 ft","Putting 6 ft+"];
type DraftShot=DetailedShot;
export default function DetailedRound(){const[hole,setHole]=useState(1);const[course,setCourse]=useState("Copt Heath Golf Club");const[shots,setShots]=useState<DraftShot[]>([]);const[message,setMessage]=useState("");useEffect(()=>{const saved=localStorage.getItem("vgp-detailed-draft");if(saved){const timer=setTimeout(()=>setShots(JSON.parse(saved)),0);return()=>clearTimeout(timer)}},[]);useEffect(()=>localStorage.setItem("vgp-detailed-draft",JSON.stringify(shots)),[shots]);const holeShots=shots.filter(s=>s.holeNumber===hole);const addShot=()=>setShots(all=>[...all,{id:crypto.randomUUID(),holeNumber:hole,sequence:holeShots.length+1,shotBand:bands[0],success:true,missLength:null,missDirection:null}]);const update=(id:string,changes:Partial<DraftShot>)=>setShots(all=>all.map(s=>s.id===id?{...s,...changes}:s));const remove=(id:string)=>setShots(all=>all.filter(s=>s.id!==id));const bandsSummary=useMemo(()=>bands.map((label,i)=>{const matching=shots.filter(s=>s.shotBand===label);return{id:`band-${i}`,label,opportunities:matching.length||null,successes:matching.length?matching.filter(s=>s.success).length:null}}),[shots]);const save=async()=>{const id=crypto.randomUUID();queueRound({id,recordedAt:new Date().toISOString(),courseName:course,entryMode:"detailed",bands:bandsSummary,detailedShots:shots});const result=await syncQueuedRounds();setMessage(result.synced?"Detailed round securely synced.":"Round saved safely on this device and queued to sync.");if(result.synced){setShots([]);localStorage.removeItem("vgp-detailed-draft")}};return <AppShell active="rounds"><header className="page-heading"><div><p className="eyebrow">Full round capture</p><h1>Hole-by-hole</h1><p>Record the shot you faced, your own success judgement and a simple miss pattern for every failure.</p></div><a className="secondary-action" href="/rounds/new">Quick Round</a></header>{message&&<div className="success-banner" role="status">{message}</div>}<section className="round-meta"><label>Course<input value={course} onChange={e=>setCourse(e.target.value)}/></label><div><span>{shots.length}</span><small>shots recorded</small></div></section><nav className="hole-picker" aria-label="Choose hole">{Array.from({length:18},(_,i)=>i+1).map(n=><button key={n} className={n===hole?"active":""} onClick={()=>setHole(n)}>{n}<small>{shots.filter(s=>s.holeNumber===n).length||"—"}</small></button>)}</nav><section className="shot-entry"><div className="section-heading"><div><p className="eyebrow">Hole {hole}</p><h2>{holeShots.length?`${holeShots.length} shots recorded`:"Add the first shot"}</h2></div><button className="primary-action" onClick={addShot}>Add shot</button></div>{holeShots.map((shot,index)=><article className="shot-row" key={shot.id}><span className="shot-number">{index+1}</span><label>Shot band<select value={shot.shotBand} onChange={e=>update(shot.id,{shotBand:e.target.value})}>{bands.map(b=><option key={b}>{b}</option>)}</select></label><fieldset><legend>Outcome</legend><button className={shot.success?"active":""} onClick={()=>update(shot.id,{success:true,missLength:null,missDirection:null})}>Success</button><button className={!shot.success?"active fail":""} onClick={()=>update(shot.id,{success:false})}>Failure</button></fieldset>{!shot.success&&<><label>Length<select value={shot.missLength||""} onChange={e=>update(shot.id,{missLength:(e.target.value||null) as DraftShot["missLength"]})}><option value="">—</option><option value="short">Short</option><option value="long">Long</option></select></label><label>Direction<select value={shot.missDirection||""} onChange={e=>update(shot.id,{missDirection:(e.target.value||null) as DraftShot["missDirection"]})}><option value="">—</option><option value="left">Left</option><option value="right">Right</option></select></label></>}<button className="remove-shot" onClick={()=>remove(shot.id)} aria-label={`Remove shot ${index+1}`}>×</button></article>)}</section><footer className="round-footer detailed-footer"><p>Draft saves automatically. Complete all played holes, then save once.</p><button className="primary-action" disabled={!shots.length} onClick={save}>Save detailed round</button></footer></AppShell>}
